@page "/chat"
@using sv_5a17085eb78b4b009801bbd03631dfbe.Components.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelList Channels="channels"
                     ActiveChannelId="activeChannelId"
                     OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(activeThread is null ? "full-width" : "")">
        @if (activeChannel is not null)
        {
            <MessageArea Channel="activeChannel"
                         Messages="messages"
                         ThreadSummaries="threadSummaries"
                         IsLoadingMore="isLoadingMore"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage"
                         OnLoadMore="LoadMoreMessages" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (activeThread is not null && threadMessages is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="activeThread"
                         Replies="threadMessages"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];
    private List<Message>? threadMessages;
    private Channel? activeChannel;
    private Message? activeThread;
    private int activeChannelId;
    private bool isLoadingMore;

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        activeChannelId = channelId;
        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        ComputeThreadSummaries();
        activeThread = null;
        threadMessages = null;
        await ChatService.MarkChannelReadAsync(channelId);

        // Update the local unread count
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = channels[idx];
            channels[idx] = ch with { UnreadCount = 0 };
        }
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || activeChannel is null) return;
        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(activeChannel.Id, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            ComputeThreadSummaries();
        }
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (activeChannel is null) return;
        var message = await ChatService.SendMessageAsync(activeChannel.Id, content, null);
        messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        activeThread = messages.FirstOrDefault(m => m.Id == messageId);
        if (activeThread is not null)
        {
            threadMessages = await ChatService.GetThreadAsync(messageId);
        }
    }

    private void CloseThread()
    {
        activeThread = null;
        threadMessages = null;
    }

    private async Task SendThreadReply(string content)
    {
        if (activeThread is null || activeChannel is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannel.Id, content, activeThread.Id);
        threadMessages?.Add(reply);
        ComputeThreadSummaries();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to reflect reaction change
        if (activeChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(activeChannel.Id, 0, messages.Count);
        }
    }

    private void ComputeThreadSummaries()
    {
        threadSummaries = messages
            .Where(m => m.ReplyToId is null)
            .Select(m =>
            {
                var replies = messages.Where(r => r.ReplyToId == m.Id).ToList();
                return replies.Count > 0
                    ? new ThreadSummary(m.Id, replies.Count, replies.Max(r => r.SentAt))
                    : null;
            })
            .Where(t => t is not null)
            .Cast<ThreadSummary>()
            .ToList();
    }
}

