toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Sidebar */
.chat-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    border-right: 1px solid #202225;
    overflow-y: auto;
}

::deep .channel-list-header {
    padding: 16px;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #8e9297;
}

::deep .channel-item {
    display: block;
    width: 100%;
    padding: 8px 16px;
    border: none;
    background: transparent;
    color: #dcddde;
    text-align: left;
    cursor: pointer;
    position: relative;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #34373c;
}

::deep .channel-item.active {
    background: #393c43;
    color: #fff;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #8e9297;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main message area */
.chat-main {
    width: 55%;
    display: flex;
    flex-direction: column;
    background: #36393f;
    transition: width 0.2s;
}

.chat-main.full-width {
    width: 80%;
}

::deep .message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
}

::deep .message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

::deep .message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
}

::deep .loading-indicator {
    text-align: center;
    padding: 8px;
    color: #8e9297;
    font-size: 0.8rem;
}

::deep .chat-message {
    padding: 8px 12px;
    margin-bottom: 4px;
    border-radius: 4px;
    position: relative;
    transition: background 0.1s;
}

::deep .chat-message:hover {
    background: #32353b;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

::deep .message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

::deep .message-time {
    font-size: 0.7rem;
    color: #72767d;
}

::deep .message-content {
    color: #dcddde;
    font-size: 0.9rem;
    margin-top: 4px;
    line-height: 1.4;
}

::deep .message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px 8px;
    font-size: 0.8rem;
    color: #dcddde;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .reaction-badge:hover {
    background: #3b3f45;
    border-color: #5865f2;
}

::deep .thread-link {
    background: transparent;
    border: none;
    color: #5865f2;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 0;
    margin-top: 4px;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -8px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px;
}

::deep .action-btn {
    background: transparent;
    border: none;
    padding: 4px 8px;
    cursor: pointer;
    border-radius: 3px;
    font-size: 0.85rem;
}

::deep .action-btn:hover {
    background: #3b3f45;
}

::deep .emoji-picker {
    position: absolute;
    top: -40px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 6px;
    padding: 6px 8px;
    z-index: 10;
}

::deep .emoji-option {
    background: transparent;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
}

::deep .emoji-option:hover {
    background: #3b3f45;
}

::deep .message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #202225;
    background: #36393f;
}

::deep .message-input-area textarea {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 6px;
    padding: 10px 12px;
    color: #dcddde;
    font-size: 0.9rem;
    resize: none;
    outline: none;
}

::deep .message-input-area textarea::placeholder {
    color: #72767d;
}

::deep .send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 8px 16px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    align-self: flex-end;
}

::deep .send-btn:hover:not(:disabled) {
    background: #4752c4;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread panel */
.chat-thread {
    width: 25%;
    min-width: 250px;
    background: #2f3136;
    border-left: 1px solid #202225;
    display: flex;
    flex-direction: column;
}

::deep .thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
}

::deep .thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
}

::deep .thread-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
}

::deep .close-btn {
    background: transparent;
    border: none;
    color: #8e9297;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .close-btn:hover {
    color: #fff;
    background: #3b3f45;
}

::deep .thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

::deep .thread-root-message strong {
    color: #fff;
    font-size: 0.9rem;
}

::deep .thread-root-message p {
    color: #dcddde;
    font-size: 0.85rem;
    margin: 4px 0 0;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

::deep .thread-reply {
    margin-bottom: 12px;
}

::deep .reply-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

::deep .reply-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.85rem;
}

::deep .reply-time {
    font-size: 0.7rem;
    color: #72767d;
